  ('3530b115-299a-53dc-82af-7f3c37ec0aef', null, (select id from public.skills where slug = 'read-g7-figurative-language'), null, 'hard',
   $q$The author says, "Taking care of a bridge is a marathon, not a sprint." What does this comparison mean?$q$, $q$[{"text":"Bridges are used for races, so they must be checked before each event.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Bridge repairs should be finished as quickly as possible and then ended.","is_correct":false,"misconception_token":"reversed-comparison"},{"text":"Bridge care takes steady effort over a long time, not one quick burst.","is_correct":true},{"text":"Bridge inspectors must be fast runners to reach the top of the cables.","is_correct":false,"misconception_token":"literal-reading"}]$q$::jsonb, $q$Bridge care takes steady effort over a long time, not one quick burst.$q$, $q$A marathon is long and steady while a sprint is short and fast, and the author adds that "The work never really ends." Finishing repairs quickly and stopping describes a sprint, which the author says bridge care is not.$q$, 'draft', 'dd2590a3-c0e6-5a34-89a6-fa7468410075')
